enum HdOmniSensorDirtyBits : PXR_NS::HdDirtyBits
{
    OmniSensorDirtyClean = 0,
    OmniSensorDirtyAttributes = 1 << 0,
    OmniSensorDirtyTransform = 1 << 1,
    OmniSensorDirtyVisibility = 1 << 2,
    OmniSensorDirtyAll = OmniSensorDirtyAttributes | OmniSensorDirtyTransform | OmniSensorDirtyVisibility,
};

enum HdOmniLensDistortionDirtyBits : PXR_NS::HdDirtyBits
{
    OmniLensDistortionDirtyAttributes = PXR_NS::HdCamera::DirtyWindowPolicy << 1
};

using CameraAttributesMap = std::map<PXR_NS::TfToken, PXR_NS::VtValue>;

enum HdOmniProjectorAPIDirtyBits : PXR_NS::HdDirtyBits
{
    OmniProjectorAPIAttributes = PXR_NS::HdCoordSys::DirtyTransform << 1,
    OmniProjectorAPIDirtyLast = OmniProjectorAPIAttributes
};

enum HdOmniDecalDirtyBits : PXR_NS::HdDirtyBits
{
    OmniDecalDirtyMaterialBinding = OmniProjectorAPIDirtyLast << 1,
    OmniDecalDirtyAttributes = OmniProjectorAPIDirtyLast << 2,
    OmniDecalDirtyVisibility = OmniProjectorAPIDirtyLast << 3,
    OmniDecalDirtyExtent = OmniProjectorAPIDirtyLast << 4
};

struct HdOmniProjectorAPI
{
    PXR_NS::TfToken type{ "cubic" };
    PXR_NS::TfToken space{ "objectMeters" };
    int inputSpace = 0;
    PXR_NS::GfVec3d translate{ 0, 0, 0 };
    PXR_NS::GfVec3d rotate{ 0, 0, 0 };
    PXR_NS::GfVec3d scale{ 1, 1, 1 };
    PXR_NS::GfVec3d uvTranslate{ 0, 0, 0 };
    PXR_NS::GfVec3d uvRotate{ 0, 0, 0 };
    PXR_NS::GfVec3d uvScale{ 1, 1, 1 };
};

inline std::ostream& operator<<(std::ostream& os, const HdOmniProjectorAPI& api)
{
    os << "HdOmniProjectorAPI("
       << "type=" << api.type << ", "
       << "space=" << api.space << ", "
       << "inputSpace=" << api.inputSpace << ", "
       << "translate=" << api.translate << ", "
       << "rotate=" << api.rotate << ", "
       << "scale=" << api.scale << ", "
       << "uvTranslate=" << api.uvTranslate << ", "
       << "uvRotate=" << api.uvRotate << ", "
       << "uvScale=" << api.uvScale << ")";
    return os;
}

inline bool operator==(const HdOmniProjectorAPI& lhs, const HdOmniProjectorAPI& rhs)
{
    return lhs.type == rhs.type &&
           lhs.space == rhs.space &&
           lhs.inputSpace == rhs.inputSpace &&
           lhs.translate == rhs.translate &&
           lhs.rotate == rhs.rotate &&
           lhs.scale == rhs.scale &&
           lhs.uvTranslate == rhs.uvTranslate &&
           lhs.uvRotate == rhs.uvRotate &&
           lhs.uvScale == rhs.uvScale;
}

inline bool operator!=(const HdOmniProjectorAPI& lhs, const HdOmniProjectorAPI& rhs)
{
    return !(lhs == rhs);
}

struct HdOmniDecalAttributes
{
    bool enabled = true;
    PXR_NS::TfToken faceMode{ "front" };
    int priority = 0;
    int outputSpace = 0;
};

inline std::ostream& operator<<(std::ostream& os, const HdOmniDecalAttributes& attributes)
{
    os << "HdOmniDecalAttributes("
       << "enabled=" << attributes.enabled << ", "
       << "faceMode=" << attributes.faceMode << ", "
       << "priority=" << attributes.priority << ", "
       << "outputSpace=" << attributes.outputSpace << ")";
    return os;
}

inline bool operator==(const HdOmniDecalAttributes& lhs, const HdOmniDecalAttributes& rhs)
{
    return lhs.enabled == rhs.enabled &&
           lhs.faceMode == rhs.faceMode &&
           lhs.priority == rhs.priority &&
           lhs.outputSpace == rhs.outputSpace;
}

inline bool operator!=(const HdOmniDecalAttributes& lhs, const HdOmniDecalAttributes& rhs)
{
    return !(lhs == rhs);
}

